tokens.css:
--color-bg: #faf7f2;
--color-surface: #ffffff;
--color-text: #2b2622;
--color-text-muted: #6e655c;
--color-border: #e3dbcf;
--color-primary: #2a1f61;
--color-on-primary: #ffffff;
--color-accent: #fffcfb;
--color-on-accent: #ffffff;
--font-display: "Syne", system-ui, sans-serif;
--font-body: "Epilogue", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 18px;
--text-lg: 23px;
--text-xl: 28px;
--text-2xl: 35px;
--text-3xl: 44px;
--radius-control: 6px;
--radius-card: 12px;
--space-section: 136px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
